inputs.value:
`---
- name: Windows Patching
  hosts: windows
  gather_facts: no
  become: yes
  become_method: runas
  become_user: Administrator

  vars:
    folder_path_to_store_kbs: ${JSON.stringify($kb_folder_path)}
    host_kb_map: ${JSON.stringify($host_kb_and_sys_info_map)}

  tasks:

    - name: Normalize host KB list
      set_fact:
        host_kbs_normalized: "{{ host_kb_map[inventory_hostname].kbList | default([]) }}"

    - name: Get system info
      set_fact:
        sys_info: "{{ host_kb_map[inventory_hostname].systemInfo | default({}) }}"

    - name: Set windows system info
      set_fact:
        product_name: "{{ sys_info.productName | default('') }}"
        windows_display_version: "{{ sys_info.displayVersion | default('') }}"
        architecture: "{{ sys_info.architecture | default('') }}"

    - name: Find KB files locally
      win_shell: |
        $kbs = @({{ host_kbs_normalized | map('to_json') | join(', ') }})
        $baseLocalFolder = "{{ folder_path_to_store_kbs }}"
        $productName = "{{ product_name }}"
        $displayVersion = "{{ windows_display_version }}"
        $arch = "{{ architecture }}"

        $files = @()

        foreach ($kb in $kbs) {
            if (-not (Test-Path $baseLocalFolder)) { continue }

            $matchedFiles = @()

            $pattern1 = "*$productName*$displayVersion*$arch*$kb*"
            $matchedFiles += Get-ChildItem -Path $baseLocalFolder -Filter "$pattern1.msu" -File -ErrorAction SilentlyContinue
            $matchedFiles += Get-ChildItem -Path $baseLocalFolder -Filter "$pattern1.cab" -File -ErrorAction SilentlyContinue

            if (-not $matchedFiles) {
                $pattern2 = "*$productName*$arch*$kb*"
                $matchedFiles += Get-ChildItem -Path $baseLocalFolder -Filter "$pattern2.msu" -File -ErrorAction SilentlyContinue
                $matchedFiles += Get-ChildItem -Path $baseLocalFolder -Filter "$pattern2.cab" -File -ErrorAction SilentlyContinue
            }

            if (-not $matchedFiles) {
                $pattern3 = "*$kb*"
                $matchedFiles += Get-ChildItem -Path $baseLocalFolder -Filter "$pattern3.msu" -File -ErrorAction SilentlyContinue
                $matchedFiles += Get-ChildItem -Path $baseLocalFolder -Filter "$pattern3.cab" -File -ErrorAction SilentlyContinue
            }

            foreach ($m in $matchedFiles) {
                $files += [PSCustomObject]@{
                    KB = $kb
                    Path = $m.FullName
                    Extension = $m.Extension
                }
            }
        }

        $json = $files | ConvertTo-Json -Compress
        if (-not $json) { $json = "[]" }
        $json
      args:
        executable: powershell
      register: matched_kb_files


    - name: Store matched KBs
      set_fact:
        matched_kb_files_list: "{{ matched_kb_files.stdout | from_json }}"

    - name: Install KBs and get installation response using Event Log Monitoring
      win_shell: |
        $kbEntriesRaw = @'
        {{ matched_kb_files_list | to_json }}
        '@

        $kbEntries = $kbEntriesRaw | ConvertFrom-Json
        $pollIntervalSeconds = 120
        $timeoutMinutes = 15
        $results = @()
        $PreInstalledKBs = (Get-HotFix).HotFixID

        function Get-KBInstallStatusFromEventLog {
            param([string]$KBID)

            $events = Get-WinEvent -LogName Setup |
              Where-Object { $_.Message -like "*$KBID*" } |
              Sort-Object TimeCreated -Descending

            foreach ($event in $events) {
                if ($event.Message -like "*Another installation is already in progress*") {
                    return @("RetryableFailure", $event.Message)
                }
                if ($event.Message -like "*could not be installed*") {
                    return @("Failed", $event.Message)
                }
                if ($event.Message -like "*was successfully installed*" -or
                    $event.Message -like "*successfully changed to the Installed state*") {
                    return @("Installed", $event.Message)
                }
                if ($event.Message -like "*requires a computer restart*" -or
                    $event.Message -like "*A reboot is necessary before package*") {
                    return @("PendingReboot", $event.Message)
                }
                if ($event.LevelDisplayName -eq "Error") {
                    return @("Failed", $event.Message)
                }
            }
            return @("Unknown", "No conclusive entry yet")
        }

        foreach ($entry in $kbEntries) {
            $kbPath = $entry.Path
            $kbID = [regex]::Match($kbPath, "kb\d+", 'IgnoreCase').Value.ToUpper()

            if (!(Test-Path $kbPath)) {
                $results += [PSCustomObject]@{ KBID=$kbID; Status="MissingFile"; Message="$kbPath not found" }
                continue
            }

            if ($PreInstalledKBs -contains $kbID) {
                $results += [PSCustomObject]@{ KBID=$kbID; Status="AlreadyInstalled"; Message="$kbID was installed before patch run" }
                continue
            }

            if ($kbPath -like "*.msu") {
                Start-Process "wusa.exe" -ArgumentList @($kbPath, "/quiet", "/norestart") -NoNewWindow
            } elseif ($kbPath -like "*.cab") {
                Start-Process "DISM.exe" -ArgumentList @("/Online", "/Add-Package", "/PackagePath:$kbPath", "/NoRestart") -NoNewWindow
            } else {
                $results += [PSCustomObject]@{ KBID=$kbID; Status="Unsupported"; Message="Unsupported file type" }
                continue
            }

            $start = Get-Date
            $end = $start.AddMinutes($timeoutMinutes)
            $finalStatus = "Unknown"
            $finalMessage = ""

            while ((Get-Date) -lt $end) {
                Start-Sleep -Seconds $pollIntervalSeconds
                $status, $msg = Get-KBInstallStatusFromEventLog -KBID $kbID

                if ($status -in @("Installed", "PendingReboot", "Failed")) {
                    $finalStatus = $status
                    $finalMessage = $msg
                    break
                }

                if ($status -eq "RetryableFailure") {
                    $finalStatus = "RetryableFailure"
                    $finalMessage = $msg
                }
            }

            if ($finalStatus -in @("Unknown", "RetryableFailure")) {
                $finalMessage = "Timed out or retryable failure. Manual verification required. Last message: $finalMessage"
            }

            $results += [PSCustomObject]@{ KBID=$kbID; Status=$finalStatus; Message=$finalMessage }
        }

        if ($results) { $results | ConvertTo-Json -Compress }
      args:
        executable: powershell
      register: kb_status

    - name: Show final installation status
      debug:
        msg: "{{ kb_status.stdout }}"
      when: kb_status is defined and kb_status.stdout | length > 0
`

then.function:
function extractKbStatus(ansibleOutput, host_kb_details_map) {
  const resultMap = {};

  if (!ansibleOutput?.plays) {
    return resultMap;
  }

  for (const play of ansibleOutput.plays) {
    for (const taskEntry of play.tasks || []) {
      if (taskEntry?.task?.name !== "Show final installation status") continue;

      for (const [host, hostData] of Object.entries(taskEntry.hosts || {})) {
        const msg = hostData?.msg;
        const kbList = Array.isArray(msg) ? msg : msg ? [msg] : [];

        let hostStatus = "success";

        for (const kb of kbList) {
          const status = kb?.Status?.toLowerCase?.();

          if (status === "failed") {
            hostStatus = "failed";
            break;
          }
        }
        let server_ip = host_kb_details_map[host]?.systemInfo?.serverIp
        resultMap[server_ip] = { status: hostStatus };
      }
    }
  }
  return resultMap;
}

$patch_summary = extractKbStatus($result, $host_kb_and_sys_info_map)

function createServerStatusMap(hosts) {
  const map = {};

  for (const hostKey in hosts) {
    const serverIp = hosts[hostKey]?.systemInfo?.serverIp;
    if (serverIp) {
      map[serverIp] = {
        status: "failed"
      };
    }
  }

  return map;
}

$patch_summary = createServerStatusMap($host_kb_and_sys_info_map)
